// Délai de livraison EcoFlow (Espagne péninsulaire : 3 à 5 jours ouvrés, donné par David le 11/11).
// Affiché sous le prix des fiches EcoFlow en stock (SKU SV-ECF…), en français ou en espagnol.
add_action( 'woocommerce_single_product_summary', function () {
	global $product;
	if ( ! $product || 0 !== strpos( (string) $product->get_sku(), 'SV-ECF' ) || ! $product->is_in_stock() ) {
		return;
	}
	$es   = 0 === strpos( get_locale(), 'es' );
	$text = $es
		? '<strong>Envío a España peninsular: 3 a 5 días laborables.</strong>'
		: '<strong>Livraison en Espagne péninsulaire : 3 à 5 jours ouvrés.</strong>';
	echo '<p class="sv-delai-livraison" style="margin:0 0 1em;padding:.5em .75em;border-left:3px solid #C89B3C;background:#FAEEDA;color:#3D2E0A;">' . $text . '</p>';
}, 25 );
